<?php

# @autogenerated
declare(strict_types=1);

use Civi\Lughauth\Features\Access\User\Domain\UserRef;
use Civi\Lughauth\Features\Access\TrustedClient\Domain\TrustedClientRef;
use Civi\Lughauth\Features\Access\UserGrantedClientScopes\Domain\ValueObject\UserGrantedClientScopesUserVO;
use Civi\Lughauth\Features\Access\UserGrantedClientScopes\Domain\ValueObject\UserGrantedClientScopesTrustedClientVO;
use Civi\Lughauth\Features\Access\UserGrantedClientScopes\Domain\ValueObject\UserGrantedClientScopesScopeVO;
use Civi\Lughauth\Features\Access\UserGrantedClientScopes\Domain\ValueObject\UserGrantedClientScopesGrantedVO;
use Civi\Lughauth\Features\Access\UserGrantedClientScopes\Domain\ValueObject\UserGrantedClientScopesDecisionAtVO;
use Civi\Lughauth\Features\Access\UserGrantedClientScopes\Domain\ValueObject\UserGrantedClientScopesVersionVO;
use Civi\Lughauth\Features\Access\UserGrantedClientScopes\Domain\UserGrantedClientScopesAttributes;
use PHPUnit\Framework\TestCase;

final class UserGrantedClientScopesAttributesUnitTest extends TestCase
{
    public function test(): void
    {
        $value = new UserGrantedClientScopesAttributes();
        $userOneValue = new UserRef('one');
        $userOtherValue = new UserRef('other');
        $copy = $value->user($userOneValue);
        $this->assertSame($value, $copy);
        $this->assertEquals(new UserRef('one'), $value->getUser());
        $this->assertNotEquals(new UserRef('other'), $value->getUser());
        $this->assertEquals(new UserRef('one'), $value->getUserOrDefault(UserGrantedClientScopesUserVO::from($userOtherValue))->value());
        $this->assertNotEquals(new UserRef('other'), $value->getUserOrDefault(UserGrantedClientScopesUserVO::from($userOtherValue))->value());
        $value->unsetUser();
        $this->assertEquals(new UserRef('other'), $value->getUserOrDefault(UserGrantedClientScopesUserVO::from($userOtherValue))->value());
        $this->assertNotEquals(new UserRef('one'), $value->getUserOrDefault(UserGrantedClientScopesUserVO::from($userOtherValue))->value());
        $trustedClientOneValue = new TrustedClientRef('one');
        $trustedClientOtherValue = new TrustedClientRef('other');
        $copy = $value->trustedClient($trustedClientOneValue);
        $this->assertSame($value, $copy);
        $this->assertEquals(new TrustedClientRef('one'), $value->getTrustedClient());
        $this->assertNotEquals(new TrustedClientRef('other'), $value->getTrustedClient());
        $this->assertEquals(new TrustedClientRef('one'), $value->getTrustedClientOrDefault(UserGrantedClientScopesTrustedClientVO::from($trustedClientOtherValue))->value());
        $this->assertNotEquals(new TrustedClientRef('other'), $value->getTrustedClientOrDefault(UserGrantedClientScopesTrustedClientVO::from($trustedClientOtherValue))->value());
        $value->unsetTrustedClient();
        $this->assertEquals(new TrustedClientRef('other'), $value->getTrustedClientOrDefault(UserGrantedClientScopesTrustedClientVO::from($trustedClientOtherValue))->value());
        $this->assertNotEquals(new TrustedClientRef('one'), $value->getTrustedClientOrDefault(UserGrantedClientScopesTrustedClientVO::from($trustedClientOtherValue))->value());
        $scopeOneValue = 'one';
        $scopeOtherValue = 'other';
        $copy = $value->scope($scopeOneValue);
        $this->assertSame($value, $copy);
        $this->assertEquals('one', $value->getScope());
        $this->assertNotEquals('other', $value->getScope());
        $this->assertEquals('one', $value->getScopeOrDefault(UserGrantedClientScopesScopeVO::from($scopeOtherValue))->value());
        $this->assertNotEquals('other', $value->getScopeOrDefault(UserGrantedClientScopesScopeVO::from($scopeOtherValue))->value());
        $value->unsetScope();
        $this->assertEquals('other', $value->getScopeOrDefault(UserGrantedClientScopesScopeVO::from($scopeOtherValue))->value());
        $this->assertNotEquals('one', $value->getScopeOrDefault(UserGrantedClientScopesScopeVO::from($scopeOtherValue))->value());
        $grantedOneValue = true;
        $grantedOtherValue = false;
        $copy = $value->granted($grantedOneValue);
        $this->assertSame($value, $copy);
        $this->assertEquals(true, $value->isGranted());
        $this->assertNotEquals(false, $value->isGranted());
        $this->assertEquals(true, $value->getGrantedOrDefault(UserGrantedClientScopesGrantedVO::from($grantedOtherValue))->value());
        $this->assertNotEquals(false, $value->getGrantedOrDefault(UserGrantedClientScopesGrantedVO::from($grantedOtherValue))->value());
        $value->unsetGranted();
        $this->assertEquals(false, $value->getGrantedOrDefault(UserGrantedClientScopesGrantedVO::from($grantedOtherValue))->value());
        $this->assertNotEquals(true, $value->getGrantedOrDefault(UserGrantedClientScopesGrantedVO::from($grantedOtherValue))->value());
        $decisionAtOneValue = (new \DateTimeImmutable('1980-08-20T14:32:45.123Z'));
        $decisionAtOtherValue = (new \DateTimeImmutable('1981-09-06T14:32:45.123Z'));
        $copy = $value->decisionAt($decisionAtOneValue);
        $this->assertSame($value, $copy);
        $this->assertEquals((new \DateTimeImmutable('1980-08-20T14:32:45.123Z')), $value->getDecisionAt());
        $this->assertNotEquals((new \DateTimeImmutable('1981-09-06T14:32:45.123Z')), $value->getDecisionAt());
        $this->assertEquals((new \DateTimeImmutable('1980-08-20T14:32:45.123Z')), $value->getDecisionAtOrDefault(UserGrantedClientScopesDecisionAtVO::from($decisionAtOtherValue))->value());
        $this->assertNotEquals((new \DateTimeImmutable('1981-09-06T14:32:45.123Z')), $value->getDecisionAtOrDefault(UserGrantedClientScopesDecisionAtVO::from($decisionAtOtherValue))->value());
        $value->unsetDecisionAt();
        $this->assertEquals((new \DateTimeImmutable('1981-09-06T14:32:45.123Z')), $value->getDecisionAtOrDefault(UserGrantedClientScopesDecisionAtVO::from($decisionAtOtherValue))->value());
        $this->assertNotEquals((new \DateTimeImmutable('1980-08-20T14:32:45.123Z')), $value->getDecisionAtOrDefault(UserGrantedClientScopesDecisionAtVO::from($decisionAtOtherValue))->value());
        $versionOneValue = 1;
        $versionOtherValue = 2;
        $copy = $value->version($versionOneValue);
        $this->assertSame($value, $copy);
        $this->assertEquals(1, $value->getVersion());
        $this->assertNotEquals(2, $value->getVersion());
        $this->assertEquals(1, $value->getVersionOrDefault(UserGrantedClientScopesVersionVO::from($versionOtherValue))->value());
        $this->assertNotEquals(2, $value->getVersionOrDefault(UserGrantedClientScopesVersionVO::from($versionOtherValue))->value());
        $value->unsetVersion();
        $this->assertEquals(2, $value->getVersionOrDefault(UserGrantedClientScopesVersionVO::from($versionOtherValue))->value());
        $this->assertNotEquals(1, $value->getVersionOrDefault(UserGrantedClientScopesVersionVO::from($versionOtherValue))->value());
        $this->assertSame($value, $copy);
    }
}
